function numberOfWays(n, x) {
  const MOD = 1000000007;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;

  for (let base = 1; base ** x <= n; base++) {
    const power = base ** x;
    for (let sum = n; sum >= power; sum--) {
      dp[sum] = (dp[sum] + dp[sum - power]) % MOD;
    }
  }
  return dp[n];
}

