function numberOfWays(n, x) {
  // Choose the integers in increasing order: count(smallest, remaining) is the number of sets of
  // integers >= smallest whose powers add up to remaining, remembered so repeated states are free.
  const MOD = 1000000007;
  const memo = new Map();
  const count = (smallest, remaining) => {
    if (remaining === 0) return 1;
    const key = smallest + ',' + remaining;
    if (memo.has(key)) return memo.get(key);
    let ways = 0;
    for (let a = smallest; Math.pow(a, x) <= remaining; a++) ways = (ways + count(a + 1, remaining - Math.pow(a, x))) % MOD;
    memo.set(key, ways);
    return ways;
  };
  return count(1, n);
}

